<?php
require __DIR__.'/test_support.php';['db'=>$db,'fixture'=>$f]=erpTestFixture();
require __DIR__.'/../includes/routine_service.php';require __DIR__.'/../includes/auth.php';require __DIR__.'/../includes/functions.php';
Auth::startSession();$_SESSION=['user_id'=>$f['ids']['teacher'],'school_id'=>1,'role'=>'teacher'];
$class=schoolRecord($db,'classes',$f['class'],1);$teacher=$f['ids']['teacher'];$subject=$f['subject'];
$db->prepare('UPDATE class_subjects SET weekly_periods=0 WHERE class_id=?')->execute([$class['id']]);
$db->prepare('UPDATE class_subjects SET weekly_periods=5 WHERE class_id=? AND subject_id=?')->execute([$class['id'],$subject]);
$rows=routineSubjects($db,1,$class['id']);$built=buildClassRoutine($db,1,$class,$rows,[1,2,3,4,5],2);
erpEqual($built['unplaced'],0,'All requested periods placed');
foreach([1,2,3,4,5] as $day){erpEqual($built['grid'][$day][1]['teacher_id'],$teacher,'Class teacher every first period');erpEqual($built['grid'][$day][1]['subject_id'],$subject,'First period uses own subject');erpEqual($built['grid'][$day][2]['subject_id'],null,'No invented periods');}
erpReject(fn()=>buildClassRoutine($db,1,$class,$rows,[7],2),'Sunday rejected');erpReject(fn()=>buildClassRoutine($db,1,$class,$rows,[6],2),'Saturday rejected');
erpReject(fn()=>validateRoutineSlot($db,1,$class['id'],1,1,null,null),'First period cannot be freed');
erpReject(fn()=>validateRoutineSlot($db,1,$class['id'],1,2,$subject,null),'Unstaffed subject rejected');
$unassigned=(int)$db->query("SELECT id FROM classes WHERE school_id=1 AND class_teacher_id IS NULL LIMIT 1")->fetchColumn();
erpReject(fn()=>validateRoutineSlot($db,1,$unassigned,1,1,null,null),'Manual first period requires an assigned class teacher');
$short=$rows;foreach($short as &$r)$r['weekly_periods']=($r['subject_id']==$subject)?4:0;unset($r);
erpReject(fn()=>buildClassRoutine($db,1,$class,$short,[1,2,3,4,5],2),'Insufficient first periods rejected');
$credit=$db->query('SELECT credit_hours FROM class_subjects WHERE class_id='.$class['id'].' AND subject_id='.$subject)->fetchColumn();
$input=[];foreach($rows as $r)$input[$r['id']]=['weekly'=>$r['subject_id']==$subject?'6':'0','teachers'=>$r['subject_id']==$subject?[$teacher]:[]];
$db->beginTransaction();saveRoutineRequirements($db,1,$class['id'],$input);$db->commit();
erpEqual($db->query('SELECT credit_hours FROM class_subjects WHERE class_id='.$class['id'].' AND subject_id='.$subject)->fetchColumn(),$credit,'Weekly periods never change grading credits');
erpReject(fn()=>saveRoutineRequirements($db,1,$class['id'],[$f['otherClass']+9999=>['weekly'=>5]]),'Cross-class mapping rejected');
$db->prepare("INSERT INTO subjects(school_id,name_en,code,type,is_hidden) VALUES(1,'Synthetic Optional','SYN-OPT','optional',0)")->execute();$opt=(int)$db->lastInsertId();
$db->prepare('INSERT INTO class_subjects(school_id,class_id,subject_id,teacher_id,is_optional,is_active) VALUES(1,?,?,?,1,0)')->execute([$class['id'],$opt,$teacher]);
erpCheck(!in_array($opt,array_column(learningSubjects($db,1,$class['id'],'teacher',$teacher),'id')),'Inactive school elective is excluded even when its teacher remains assigned');
erpEqual(learningSubjects($db,1,0,'school_admin',$teacher),[],'Class required before subjects');
erpReject(fn()=>validateTeacherLearningRequest($db,1,'learning','questions.php',['action_quick_add_class'=>1],[]),'Removed quick class route rejected');
$other=(int)$db->query('SELECT subject_id FROM class_subjects WHERE class_id='.$class['id'].' AND subject_id<>'.$subject.' AND subject_id<>'.$opt.' LIMIT 1')->fetchColumn();
erpReject(fn()=>validateTeacherLearningRequest($db,1,'learning','paper_generator.php',['class_id'=>$class['id'],'subject_id'=>$other],[]),'Forged paper/grid other subject rejected');
erpReject(fn()=>validateSchoolReferences($db,1,'learning',[],['class'=>[$class['id']]]),'Array identifiers rejected');
$html=printSignature('<script>bad</script>','Head Teacher','../evil.php');erpCheck(!str_contains($html,'<script>')&&!str_contains($html,'evil.php'),'Signature content and paths escaped');
erpCheck(strpos($html,'print-signature-image')<strpos($html,'print-signature-name'),'Signature before name and post');
erpCheck(str_contains(schoolPrintSignatures($db,1,[],999999),'Head Teacher'),'Missing legacy class signature remains safe');
erpCheck(!Auth::login(['teacher'],'TestPassword123!'),'Array login identity rejected');
$_SERVER['REMOTE_ADDR']='127.0.0.21';
erpCheck(!Auth::login('teacher','wrong-password'),'Invalid password rejected');
$accountKey=hash('sha256','account|teacher');
$q=$db->prepare('SELECT COUNT(*) FROM login_attempts WHERE identity_key=?');$q->execute([$accountKey]);
erpEqual((int)$q->fetchColumn(),1,'Failed login records aggregate account attempt');
$insert=$db->prepare('INSERT INTO login_attempts(identity_key,attempted_at) VALUES(?,?)');
for($i=1;$i<25;$i++)$insert->execute([$accountKey,time()]);
$_SERVER['REMOTE_ADDR']='127.0.0.22';
erpCheck(!Auth::login('teacher','TestPassword123!'),'Account limit cannot be bypassed by another IP');
$db->exec('DELETE FROM login_attempts');
for($i=0;$i<100;$i++)$insert->execute([hash('sha256','network|127.0.0.22'),time()]);
erpCheck(!Auth::login('school_admin','TestPassword123!'),'Network limit applies across accounts');
$db->exec('DELETE FROM login_attempts');
erpCheck(Auth::login('teacher','TestPassword123!'),'Login succeeds when temporary limits cleared');
echo 'Routine, learning and print safety passed: '.$GLOBALS['erp_checks']." checks\n";
